// And groups predicates with the AND operator between them.
func And(predicates ...predicate.VerificationAttempts) predicate.VerificationAttempts {
	return predicate.VerificationAttempts(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.VerificationAttempts) predicate.VerificationAttempts {
	return predicate.VerificationAttempts(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.VerificationAttempts) predicate.VerificationAttempts {
	return predicate.VerificationAttempts(sql.NotPredicates(p))
}
